options.styles:
:root{--fs-accent:#00c8ff;--fs-text:#eef4f8;--fs-dim:#8fa3b3;--fs-line:rgba(255,255,255,.08);--fs-mono:ui-monospace,"JetBrains Mono",Menlo,Consolas,monospace;}
.fs-banner{display:flex;align-items:center;justify-content:space-between;gap:16px;flex-wrap:wrap;font-family:var(--fs-mono);color:var(--fs-dim);padding:6px 4px 6px;}
.fs-banner-left{display:flex;align-items:center;gap:12px;font-size:12px;letter-spacing:.04em;}
.fs-banner-right{display:flex;align-items:center;gap:8px;flex-wrap:wrap;}
.fs-prompt{color:var(--fs-accent);}.fs-path{color:var(--fs-text);margin-left:6px;}.fs-sep{opacity:.35;}
.fs-title{color:var(--fs-text);font-weight:700;letter-spacing:.14em;font-size:13px;}.fs-thin{font-weight:400;color:var(--fs-dim);}
.fs-pill{display:inline-flex;align-items:center;gap:8px;padding:5px 12px;border:1px solid rgba(255,255,255,.16);border-radius:999px;color:var(--fs-text);font-family:var(--fs-mono);font-size:11px;letter-spacing:.12em;text-decoration:none;background:rgba(8,12,18,.6);}
.fs-pill--ok{border-color:rgba(0,200,255,.35);background:rgba(0,200,255,.12);}
.fs-pill--link:hover{border-color:var(--fs-accent);}
.fs-dot{width:7px;height:7px;border-radius:50%;background:var(--fs-accent);animation:fs-pulse 1.8s ease-out infinite;}
@keyframes fs-pulse{0%{box-shadow:0 0 0 0 rgba(0,200,255,.55)}100%{box-shadow:0 0 0 9px rgba(0,200,255,0)}}

options.afterRender:
(function(){
  var root = (typeof context !== 'undefined' && context.element) ? context.element : (typeof element !== 'undefined' ? element : document);
  var el = root.querySelector ? root.querySelector('#fs-clock') : null;
  if (!el) return;
  function tick(){ el.textContent = new Date().toLocaleTimeString('pt-BR',{hour12:false}); }
  tick(); if (el._t) clearInterval(el._t); el._t = setInterval(tick, 1000);
})();

options.getOption:
// Business Charts — ranking horizontal (terms x soma de bytes), sem date histogram
const ctx = (typeof context !== 'undefined') ? context : null;
const frames = ctx ? ctx.panel.data.series : data.series;
const vals = (f) => (f && f.values) ? (f.values.toArray ? f.values.toArray() : Array.from(f.values)) : [];
const fr = frames[0]; if (!fr) return { title: { text: 'sem dados', textStyle: { color: '#8fa3b3', fontSize: 12 } } };
const key = fr.fields.find(f => f.type === 'string'); const val = fr.fields.find(f => f.type === 'number');
const rows = vals(key).map((k, i) => [k, vals(val)[i] || 0]).sort((a, b) => a[1] - b[1]).slice(-12);
const fmt = (v) => v >= 1e9 ? (v/1e9).toFixed(1)+' GB' : v >= 1e6 ? (v/1e6).toFixed(1)+' MB' : v >= 1e3 ? (v/1e3).toFixed(0)+' KB' : v+' B';
const mono = 'ui-monospace, JetBrains Mono, Menlo, Consolas, monospace';
return {
  backgroundColor: 'transparent', animationDuration: 700,
  grid: { left: 8, right: 70, top: 8, bottom: 8, containLabel: true },
  tooltip: { trigger: 'axis', axisPointer: { type: 'shadow' }, backgroundColor: 'rgba(8,12,18,.95)', borderColor: 'rgba(0,200,255,.35)', textStyle: { color: '#eef4f8', fontFamily: mono, fontSize: 11 }, valueFormatter: fmt },
  xAxis: { type: 'value', show: false },
  yAxis: { type: 'category', data: rows.map(r => r[0]), axisLine: { show: false }, axisTick: { show: false }, axisLabel: { color: '#cfd8e3', fontFamily: mono, fontSize: 11 } },
  series: [{ type: 'bar', data: rows.map(r => r[1]), barWidth: 14,
    itemStyle: { borderRadius: [0, 4, 4, 0], color: { type: 'linear', x: 0, y: 0, x2: 1, y2: 0, colorStops: [{ offset: 0, color: 'rgba(0,200,255,.35)' }, { offset: 1, color: '#00c8ff' }] } },
    label: { show: true, position: 'right', color: '#8fa3b3', fontFamily: mono, fontSize: 10, formatter: (p) => fmt(p.value) } }]
};
